-- PT120-S1-Q10. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT120-S1-Q10$batch06$ AND q.stimulus=$batch06$Editorial: Many observers note with dismay the decline in the number of nongovernmental, voluntary community organizations. They argue that this decline is caused by the corresponding growth of government services once provided by these voluntary community groups. But this may not be true. The increase in government services may coincide with a decrease in volunteerism, but the former does not necessarily cause the latter; the latter may indeed cause the former.$batch06$ AND q.prompt=$batch06$The editorial undermines the conclusion of the causal argument by$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT120-S1-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT120-S1-Q10$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S1-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT120-S1-Q10$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$The claim that growing government services caused the decline in volunteer groups may not be true.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$The two trends go together, but the causation could run the other way: the decline in volunteering could have caused the growth in government services.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The observers see two things moving together and pick a direction: government growth causes volunteer decline. The editorial does not deny the correlation. It points out that the arrow could run backward, with government stepping in because volunteers stepped out.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Offering another explanation of the correlation.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT120-S1-Q10$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The editorial does not deny causation. It suggests a different causal direction, "the latter may indeed cause the former," which is still causation.$batch06$), ($batch06$B$batch06$, $batch06$This is the most popular wrong answer, because the editorial does push back on the observers. But it never offers a case that breaks the correlation. It accepts that the two trends go together and only questions which one drives the other.$batch06$), ($batch06$C$batch06$, $batch06$Nothing is proved about people's motives for volunteering.$batch06$), ($batch06$D$batch06$, $batch06$The correlation is the two trends moving together. The other explanation is that the decline in volunteering caused the growth in government services.$batch06$), ($batch06$E$batch06$, $batch06$The editorial proves nothing about what governments must do.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT120-S1-Q10$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
